CREATE TYPE "course_status" AS ENUM (
  'planned',
  'active',
  'completed',
  'cancelled'
);

CREATE TYPE "hackathon_status" AS ENUM (
  'planned',
  'active',
  'completed',
  'cancelled'
);

CREATE TYPE "week_day" AS ENUM (
  'monday',
  'tuesday',
  'wednesday',
  'thursday',
  'friday',
  'saturday',
  'sunday'
);

CREATE TYPE "member_role" AS ENUM (
  'leader',
  'member'
);

CREATE TABLE "courses" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" varchar(150) NOT NULL,
  "description" text,
  "start_date" date,
  "end_date" date,
  "status" course_status NOT NULL DEFAULT 'planned',
  "room_id" integer,
  "supervisor_id" integer UNIQUE,
  "created_at" timestamp DEFAULT (now())
);

CREATE TABLE "instructors" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "full_name" varchar(150) NOT NULL,
  "email" varchar(255) UNIQUE NOT NULL,
  "phone" varchar(25),
  "specialization" varchar(150),
  "course_id" integer,
  "created_at" timestamp DEFAULT (now())
);

CREATE TABLE "students" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "full_name" varchar(150) NOT NULL,
  "email" varchar(255) UNIQUE NOT NULL,
  "phone" varchar(25),
  "registration_date" date,
  "course_id" integer,
  "created_at" timestamp DEFAULT (now())
);

CREATE TABLE "supervisors" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "full_name" varchar(150) NOT NULL,
  "email" varchar(255) UNIQUE NOT NULL,
  "phone" varchar(25),
  "created_at" timestamp DEFAULT (now())
);

CREATE TABLE "rooms" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" varchar(100) UNIQUE NOT NULL,
  "building" varchar(100),
  "floor" integer,
  "capacity" integer NOT NULL,
  "equipment" text,
  "created_at" timestamp DEFAULT (now())
);

CREATE TABLE "course_schedules" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "course_id" integer NOT NULL,
  "day_of_week" week_day NOT NULL,
  "start_time" time NOT NULL,
  "end_time" time NOT NULL
);

CREATE TABLE "hackathons" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "course_id" integer UNIQUE NOT NULL,
  "title" varchar(150) NOT NULL,
  "description" text,
  "event_date" date NOT NULL,
  "start_time" time NOT NULL,
  "end_time" time NOT NULL,
  "room_id" integer,
  "instructor_id" integer,
  "status" hackathon_status NOT NULL DEFAULT 'planned',
  "created_at" timestamp DEFAULT (now())
);

CREATE TABLE "hackathon_teams" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "hackathon_id" integer NOT NULL,
  "team_name" varchar(100) NOT NULL,
  "project_title" varchar(150),
  "project_description" text,
  "final_score" decimal(5,2),
  "final_rank" integer,
  "created_at" timestamp DEFAULT (now())
);

CREATE TABLE "hackathon_team_members" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "team_id" integer NOT NULL,
  "student_id" integer UNIQUE NOT NULL,
  "member_role" member_role NOT NULL DEFAULT 'member',
  "joined_at" timestamp DEFAULT (now())
);

CREATE UNIQUE INDEX ON "course_schedules" ("course_id", "day_of_week", "start_time");

CREATE UNIQUE INDEX ON "hackathon_teams" ("hackathon_id", "team_name");

COMMENT ON TABLE "courses" IS 'Each course has one room and one supervisor when active';

COMMENT ON COLUMN "courses"."room_id" IS 'Nullable until room assignment';

COMMENT ON COLUMN "courses"."supervisor_id" IS 'Nullable until supervisor assignment';

COMMENT ON TABLE "instructors" IS 'One course can have multiple instructors';

COMMENT ON COLUMN "instructors"."course_id" IS 'Nullable until assigned';

COMMENT ON TABLE "students" IS 'Each student belongs to at most one course';

COMMENT ON COLUMN "students"."course_id" IS 'Nullable until enrolled';

COMMENT ON TABLE "supervisors" IS 'One supervisor can manage at most one course';

COMMENT ON TABLE "rooms" IS 'Rooms can host different courses at different times';

COMMENT ON TABLE "course_schedules" IS 'A course may have multiple weekly sessions';

COMMENT ON TABLE "hackathons" IS 'One final hackathon per course';

COMMENT ON COLUMN "hackathons"."room_id" IS 'Nullable until assigned';

COMMENT ON COLUMN "hackathons"."instructor_id" IS 'Nullable until assigned';

COMMENT ON TABLE "hackathon_teams" IS 'Each hackathon contains multiple competing teams';

COMMENT ON COLUMN "hackathon_teams"."final_score" IS 'Nullable before evaluation';

COMMENT ON COLUMN "hackathon_teams"."final_rank" IS 'Nullable before results';

COMMENT ON TABLE "hackathon_team_members" IS 'A student can belong to only one hackathon team';

ALTER TABLE "courses" ADD FOREIGN KEY ("room_id") REFERENCES "rooms" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "supervisors" ADD FOREIGN KEY ("id") REFERENCES "courses" ("supervisor_id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "instructors" ADD FOREIGN KEY ("course_id") REFERENCES "courses" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "students" ADD FOREIGN KEY ("course_id") REFERENCES "courses" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "course_schedules" ADD FOREIGN KEY ("course_id") REFERENCES "courses" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "courses" ADD FOREIGN KEY ("id") REFERENCES "hackathons" ("course_id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "hackathons" ADD FOREIGN KEY ("instructor_id") REFERENCES "instructors" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "hackathons" ADD FOREIGN KEY ("room_id") REFERENCES "rooms" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "hackathon_teams" ADD FOREIGN KEY ("hackathon_id") REFERENCES "hackathons" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "hackathon_team_members" ADD FOREIGN KEY ("team_id") REFERENCES "hackathon_teams" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "students" ADD FOREIGN KEY ("id") REFERENCES "hackathon_team_members" ("student_id") DEFERRABLE INITIALLY IMMEDIATE;
